  @case 'a pinned slot holds its ordinal, and joins its base by name alone'  [harness]  @ 363-376
  @case 'two pinned members holding the base plain both keep it'  [harness]  @ 380-392
  @case 'an audio slot takes no part in a base'  [harness]  @ 396-408
  @case 'tidySlots writes every live instance and the parked keeper'  [harness]  @ 412-426
  @case 'seedTidy lists the distinct roots sorted, each slot on its own'  [harness]  @ 433-447
  @case 'an unnamed slot seeds pinned, and names no base'  [harness]  @ 451-462
  @case 'an ambiguous base pins every slot carrying it, and still stands in the list'  [harness]  @ 466-481
  @case 'audio slots take no part, so an audio namesake leaves a base unambiguous'  [harness]  @ 485-499
  @case 'createAndDropMidi mints slot 0, creates a take, names it'  [harness]  @ 506-522
  @case 'createAndDropMidi allocates lowest-free index across calls'  [harness]  @ 526-537
  @case 'dropInstance pools to an existing slot'  [harness]  @ 541-552
  @case 'dropInstance overwrites a take already starting at the drop position'  [harness]  @ 556-573
  @case 'createAndDropMidi overwrites a take already starting at the create position'  [harness]  @ 577-592
  @case 'dropInstance returns nil for missing slot or missing track'  [harness]  @ 596-602
  @case 'duplicateTake clones a MIDI take into a pooled sibling'  [harness]  @ 606-621
  @case 'dropInstance and duplicateTake name the new take after the slot'  [harness]  @ 625-636
  @case 'duplicateTake returns nil for a missing track'  [harness]  @ 640-648
