  @case 'duplicateTake carries the source MIDI events into the clone'  [harness]  @ 666-677
  @case 'startIsClear only collides on an exact start match (item ~= exceptItem)'  [harness]  @ 681-696
  @case 'createAndDropMidi returns nil when no track exists'  [harness]  @ 700-705
