  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 773-782
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 785-796
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 799-807
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 811-825
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 829-845
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 848-863
  @case 'trimmed audio take keeps its trim across a move (no balloon to source)'  [harness]  @ 866-878
  @case 'moveTake shifts start; refused on start-collision; returns ok flag'  [harness]  @ 882-893
  @case 'resizeTake writes natural; rendered is min(natural, source, gap)'  [harness]  @ 897-908
